using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.UIElements;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hud = GameObject.Find("HudRoot");
        if (hud == null) { result.Log("HudRoot missing"); return; }
        var hudAsset = AssetDatabase.LoadAssetAtPath<VisualTreeAsset>("Assets/Resources/HUDTree/HudUI.uxml");
        if (hudAsset == null) { result.Log("hudAsset null"); return; }
        var panelSettings = AssetDatabase.LoadAssetAtPath<PanelSettings>("Assets/UI/PanelSettings.asset");
        var builder = hud.GetComponent<Homesteader.UI.HudUIBuilder>();
        if (builder == null) { result.Log("HudUIBuilder missing"); return; }
        var so = new SerializedObject(builder);
        var prop = so.FindProperty("_hudAsset");
        if (prop != null)
        {
            prop.objectReferenceValue = hudAsset;
            so.ApplyModifiedProperties();
            result.Log("Assigned _hudAsset to HudUI.uxml on HudRoot.");
        }
        else
        {
            result.Log("_hudAsset SerializedProperty not found.");
        }
        var doc = hud.GetComponent<UIDocument>();
        if (doc != null)
        {
            if (panelSettings != null) doc.panelSettings = panelSettings;
            if (hudAsset != null) doc.visualTreeAsset = hudAsset;
        }
        var scn = SceneManager.GetActiveScene();
        if (scn.IsValid()) EditorSceneManager.SaveScene(scn);
        result.Log("Saved scene.");
    }
}
